(function(){function copy(t){if(navigator.clipboard&&navigator.clipboard.writeText){return navigator.clipboard.writeText(t);}return new Promise(function(res,rej){try{var e=document.createElement('textarea');e.value=t;e.style.position='fixed';e.style.opacity='0';document.body.appendChild(e);e.select();document.execCommand('copy');document.body.removeChild(e);res();}catch(err){rej(err);}});}function artTitle(){var e=document.querySelector('.post-title')||document.querySelector('.blog-title');return e?e.textContent.trim():document.title;}function artUrl(){var c=document.querySelector('link[rel="canonical"]');return c?c.getAttribute('href'):location.href;}var SITE='freenav.net';var T={link:function(t,u){return u;},wechat:function(t,u){return '📖 《'+t+'》\n'+u+'\n\n微信里发给朋友，或搜「FreeNav / '+SITE+'」找到我们——更多免费 / 开源软件深度测评都在 FreeNav。';},weibo:function(t,u){return '推荐 @FreeNav 专栏《'+t+'》'+u+' #免费软件# #开源替代# （更多深度测评在 '+SITE+'）';},xiaohongshu:function(t,u){return '最近在 FreeNav 读到一篇很实用的：《'+t+'》\n'+u+'\n\nFreeNav 是个做人工精选免费 / 开源软件的站——深度测评、帮你做决定、不追踪你。整站都在 '+SITE+'。\n\n#免费软件 #开源替代 #效率工具';},headline:function(t,u){return '《'+t+'》——来自 FreeNav 专栏：\n'+u+'\n人工精选、深度测评、帮你做决定。更多在 '+SITE+'。';}};document.querySelectorAll('.share-bar').forEach(function(bar){bar.querySelectorAll('[data-share]').forEach(function(btn){btn.addEventListener('click',function(){var k=btn.getAttribute('data-share');if(k==='native'){if(navigator.share){navigator.share({title:artTitle(),url:artUrl()}).catch(function(){});}return;}var txt=T[k]?T[k](artTitle(),artUrl()):artUrl();copy(txt).then(function(){var o=btn.textContent;btn.textContent='已复制 ✓';btn.classList.add('copied');setTimeout(function(){btn.textContent=o;btn.classList.remove('copied');},1600);}).catch(function(){btn.textContent='复制失败';setTimeout(function(){btn.textContent='复制链接';},1600);});});});});})();
